The same scene, two ways:
// vanilla Three.js
const geo = new THREE.BoxGeometry(1, 1, 1);
const mat = new THREE.MeshStandardMaterial({ color: 'orange' });
const cube = new THREE.Mesh(geo, mat);
cube.position.set(0, 1, 0);
scene.add(cube);
// R3F
<mesh position={[0, 1, 0]}>
<boxGeometry args={[1, 1, 1]} />
<meshStandardMaterial color="orange" />
</mesh>
Same output. R3F wins when:
The scene composition is data-driven (mapping over an array of items → list of meshes).
You want React idioms: state, effects, suspense, context, hooks, refs.
You're already on React for the rest of the app.
R3F doesn't make Three.js faster; it makes the codebase more maintainable for React teams.

// src/App.tsx
import { Canvas } from '@react-three/fiber';
import { OrbitControls, Environment } from '@react-three/drei';
export default function App() {
return (
<Canvas
camera={{ position: [3, 3, 5], fov: 60 }}
dpr={[1, 2]} // capped pixel ratio
shadows
>
<ambientLight intensity={0.3} />
<directionalLight position={[5, 10, 5]} intensity={1.2} castShadow />
<mesh position={[0, 1, 0]} castShadow>
<boxGeometry args={[1, 1, 1]} />
<meshStandardMaterial color="orange" />
</mesh>
<mesh rotation-x={-Math.PI / 2} receiveShadow>
<planeGeometry args={[20, 20]} />
<meshStandardMaterial color="#888" />
</mesh>
<Environment preset="city" />
<OrbitControls />
</Canvas>
);
}
That's a fully-set-up Three.js scene with shadows, environment lighting, controls — in 25 lines of JSX.

import { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
function SpinningCube() {
const meshRef = useRef<THREE.Mesh>(null!);
useFrame((state, dt) => {
meshRef.current.rotation.y += dt * 0.5;
});
return (
<mesh ref={meshRef}>
<boxGeometry />
<meshStandardMaterial color="orange" />
</mesh>
);
}
useFrame runs outside React's render cycle — directly inside the render loop. Mutate refs; never call setState here unless you really want a React re-render (almost always a bug).

import { useThree } from '@react-three/fiber';
const { gl, scene, camera, size, viewport } = useThree();
For reading: fine. For modifying: prefer refs.

import { useLoader } from '@react-three/fiber';
import { GLTFLoader } from 'three-stdlib'; // or 'three/addons/loaders/GLTFLoader.js'
function Model() {
const gltf = useLoader(GLTFLoader, '/models/chair.glb');
return <primitive object={gltf.scene} />;
}
// wrap consumers in Suspense
<Canvas>
<Suspense fallback={null}>
<Model />
</Suspense>
</Canvas>
Drei provides nicer wrappers: useGLTF, useTexture, useFBX, etc.

For app-level state (selected object, settings, scores), use Zustand. It plays well with R3F because mutations don't force the canvas to re-render.
npm install zustand
// store.ts
import { create } from 'zustand';
interface GameState {
score: number;
inc: () => void;
}
export const useGame = create<GameState>((set) => ({
score: 0,
inc: () => set((s) => ({ score: s.score + 1 })),
}));
function Cube() {
const inc = useGame((s) => s.inc); // selector — no re-render on irrelevant state
return <mesh onClick={inc}><boxGeometry /><meshStandardMaterial /></mesh>;
}
function Score() {
const score = useGame((s) => s.score);
return <h1 style={{ position: 'absolute', top: 10, left: 10 }}>{score}</h1>;
}
Pattern: use Zustand selectors so components only re-render when their slice changes. Subscribe to transient updates inside useFrame for high-frequency values:
useFrame(() => {
const score = useGame.getState().score; // no subscription, just a read
// ...
});

import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, Environment, ContactShadows, Float, Html } from '@react-three/drei';
import { Physics, RigidBody } from '@react-three/rapier';
import { EffectComposer, Bloom, SMAA } from '@react-three/postprocessing';
import { Perf } from 'r3f-perf';
import { useRef, Suspense } from 'react';
function SpinningCube() {
const ref = useRef(null);
useFrame((s, dt) => { ref.current.rotation.y += dt * 0.5; });
return (
<RigidBody position={[0, 5, 0]}>
<mesh ref={ref} castShadow>
<boxGeometry />
<meshStandardMaterial color="orange" emissive="#330000" emissiveIntensity={1.5} />
</mesh>
</RigidBody>
);
}
export default function App() {
return (
<Canvas camera={{ position: [4, 4, 6], fov: 50 }} dpr={[1, 2]} shadows>
<Suspense fallback={<Html center>Loading...</Html>}>
<Physics updateLoop="independent">
<RigidBody type="fixed">
<mesh rotation-x={-Math.PI / 2} receiveShadow>
<planeGeometry args={[40, 40]} />
<meshStandardMaterial color="#888" />
</mesh>
</RigidBody>
<Float speed={2}>
<SpinningCube />
</Float>
<Environment preset="sunset" />
<ContactShadows position={[0, 0.01, 0]} opacity={0.5} blur={2} far={5} />
<EffectComposer>
<SMAA />
<Bloom intensity={0.6} luminanceThreshold={0.95} />
</EffectComposer>
<OrbitControls />
<Perf position="top-left" />
</Physics>
</Suspense>
</Canvas>
);
}
A full physics + IBL + bloom + ContactShadows + Drei Float animation app in ~50 lines.
